const prefixes = ["The Ultimate Guide to", "Smart", "2025 Expert Review of", "AI-Powered", "Proven Strategies for"];
const categories = ["Smart Parking", "Parking Management", "AI Parking Solutions", "Urban Mobility", "Parking Technology"];
const formats = ["What Cities Need to Know", "For Property Managers", "That Actually Work", "Backed by Data"];

if (!prefixes.length || !categories.length || !formats.length) {
  return [{ json: { error: "Configuration arrays are empty", timestamp: new Date().toISOString() } }];
}

const seedTopic = `${prefixes[Math.floor(Math.random() * prefixes.length)]} ${categories[Math.floor(Math.random() * categories.length)]} ${formats[Math.floor(Math.random() * formats.length)]}`;
return [{ json: { seed_topic: seedTopic, timestamp: new Date().toISOString() } }];

try {
  const openAiResponse = $input.all()[0].json;

  let topics = [];
  if (openAiResponse.choices && openAiResponse.choices[0].message) {
    try {
      topics = JSON.parse(openAiResponse.choices[0].message.content);
    } catch (e) {
      topics = [openAiResponse.choices[0].message.content];
    }
  } else if (openAiResponse.text) {
    try {
      topics = JSON.parse(openAiResponse.text);
    } catch (e) {
      topics = [openAiResponse.text];
    }
  }

  if (!Array.isArray(topics)) {
    topics = [topics];
  }

  // Select the first topic and clean it up
  let selectedTopic = topics[0] || "Natural Health Remedies";

  // Clean up the topic if it contains quotes or formatting
  if (typeof selectedTopic === 'string') {
    selectedTopic = selectedTopic.replace(/^"|"$/g, ''); // Remove surrounding quotes
    selectedTopic = selectedTopic.replace(/^\d+\.\s*/, ''); // Remove numbering like "1. "
    selectedTopic = selectedTopic.trim();
  }

  console.log('Selected topic:', selectedTopic);

  return [{
    json: {
      selected_topic: selectedTopic,
      all_options: topics,
      timestamp: new Date().toISOString(),
      raw_response: openAiResponse
    }
  }];
} catch (error) {
  return [{
    json: {
      error: 'Topic selection failed',
      details: error.message,
      fallback_topic: $input.all()[0]?.json?.seed_topic || "Natural Health Remedies",
      timestamp: new Date().toISOString()
    }
  }];
}

try {
  const inputs = $input.all();
  const openAiResponse = inputs[0].json;

  console.log("=== DEBUG: OpenAI Response ===");
  console.log(JSON.stringify(openAiResponse, null, 2));

  // Get topic data from execution context using n8n's built-in functions
