    }

    // Access execution data from Generate Topic Seed node
    const seedData = $('Generate Topic Seed').all();
    if (seedData && seedData.length > 0) {
      seedTopic = seedData[0].json.seed_topic || "";
      console.log("=== DEBUG: Seed Topic ===", seedTopic);
    }
  } catch (e) {
    console.log("Could not access previous node data:", e.message);
  }

  let blogData = {
    title: selectedTopic || "Natural Health Remedies Guide",
    content: "<p>No content was generated</p>",
    key_points: [],
    references: [],
    error: null
  };

  // Extract content from OpenAI response
  let content = "";
  if (openAiResponse && openAiResponse.choices && openAiResponse.choices[0]) {
    content = openAiResponse.choices[0].message?.content || openAiResponse.choices[0].text || "";
  } else if (openAiResponse && openAiResponse.text) {
    content = openAiResponse.text;
  }

  console.log("=== DEBUG: Raw Content ===");
  console.log(content);

  if (content && content.length > 10) {
    try {
      content = content.trim();

      // Remove markdown code blocks if present
      content = content.replace(/```json\s*/, '').replace(/```\s*$/, '');
      content = content.replace(/```\s*/, '').replace(/```\s*$/, '');

      console.log("=== DEBUG: Cleaned Content ===");
      console.log(content);

      let parsedContent;
      try {
        parsedContent = JSON.parse(content);
        console.log("=== DEBUG: Successfully Parsed JSON ===");
        console.log(JSON.stringify(parsedContent, null, 2));
      } catch (parseError) {
        console.log("=== DEBUG: JSON Parse Failed ===", parseError.message);

        // Fallback: Try to extract JSON from text
        const jsonMatch = content.match(/\{[\s\S]*\}/);
        if (jsonMatch) {
          try {
            parsedContent = JSON.parse(jsonMatch[0]);
            console.log("=== DEBUG: Extracted JSON Successfully ===");
          } catch (e) {
            console.log("=== DEBUG: Extracted JSON Parse Failed ===", e.message);

            // Generate fallback content based on topic
            const fallbackTitle = selectedTopic || seedTopic || "Smart Parking Solutions";
            const fallbackContent = `
              <h2>Introduction</h2>
              <p>Welcome to our comprehensive guide on ${fallbackTitle}. In today's rapidly evolving urban landscape, smart parking solutions are revolutionizing how cities and businesses manage their parking infrastructure.</p>

              <h2>Key Benefits</h2>
              <p>Smart parking technologies offer numerous advantages including reduced traffic congestion, increased revenue, improved user experience, and data-driven insights for better decision making.</p>

              <h2>Implementation Guide</h2>
              <p>Start your smart parking journey by assessing current infrastructure, selecting appropriate technology solutions, and partnering with experienced providers like ParkAlgo for seamless integration.</p>

              <h2>Common Challenges</h2>
              <p>Avoid common pitfalls like inadequate planning, choosing incompatible systems, or underestimating maintenance requirements. Professional consultation ensures optimal results.</p>

              <h2>Conclusion</h2>
              <p>Smart parking solutions can dramatically improve efficiency and profitability when implemented correctly. Contact ParkAlgo today to discover how AI-powered parking management can transform your operations.</p>
            `;

            parsedContent = {
              title: fallbackTitle,
              content: fallbackContent,
              key_points: ["Reduced traffic congestion", "Increased revenue potential", "Data-driven insights"],
              references: ["Smart Cities Journal", "Urban Mobility Research Institute"]
            };
            console.log("=== DEBUG: Using Fallback Content ===");
          }
        } else {
          console.log("=== DEBUG: No JSON found, using raw content ===");
          // Use raw content if no JSON structure found
          parsedContent = {
            title: selectedTopic || "Natural Health Guide",
            content: content.length > 100 ? content : `<h2>Natural Health Information</h2><p>${content}</p>`,
            key_points: [],
            references: []
          };
        }
      }

      // Merge parsed content with defaults
      blogData = {
        ...blogData,
        title: parsedContent.title || blogData.title,
        content: parsedContent.content || blogData.content,
        key_points: parsedContent.key_points || [],
        references: parsedContent.references || []
      };
    } catch (e) {
      console.log("=== DEBUG: Processing Error ===", e.message);
      blogData.content = content.length > 100 ? content : `<h2>Content Processing Error</h2><p>${content}</p>`;
      blogData.error = "Failed to process OpenAI response";
    }
  } else {
    console.log("=== DEBUG: No content received ===");
    blogData.error = "No OpenAI response received";

    // Generate emergency fallback content
    const emergencyTitle = selectedTopic || seedTopic || "Natural Health Tips";
    blogData.title = emergencyTitle;
    blogData.content = `
      <h2>Natural Health and Wellness</h2>
      <p>Discover the power of natural health approaches for better living. This guide covers essential information about ${emergencyTitle.toLowerCase()}.</p>

      <h2>Benefits of Natural Approaches</h2>
      <p>Natural health methods offer gentle, effective solutions that work with your body's natural healing processes.</p>

      <h2>Getting Started</h2>
      <p>Begin with simple lifestyle changes, proper nutrition, and evidence-based natural remedies under professional guidance.</p>

      <h2>Important Considerations</h2>
      <p>Always consult healthcare professionals before making significant changes to your health routine.</p>
    `;
    blogData.key_points = ["Natural healing", "Gentle approaches", "Professional guidance"];
    blogData.references = ["Natural Health Journal", "Wellness Research Institute"];
  }

  // Add metadata
  blogData.timestamp = new Date().toISOString();
  blogData.selected_topic = selectedTopic;
  blogData.seed_topic = seedTopic;

  console.log("=== DEBUG: Final Blog Data ===");
  console.log(JSON.stringify(blogData, null, 2));

  return [{ json: blogData }];
} catch (error) {
  console.log("=== DEBUG: Fatal Error ===", error.message);
  return [{ json: {
    error: "Failed to parse blog content",
    details: error.message,
    title: "Natural Health Guide",
    content: "<h2>Natural Health Information</h2><p>Learn about natural approaches to health and wellness. Discover gentle, effective methods for better living.</p>",
    key_points: ["Natural methods", "Gentle approaches", "Better wellness"],
    references: ["Health Research"],
    timestamp: new Date().toISOString()
  } }];
}

