try {
  const inputs = $input.all();
  const seoResponse = inputs[0].json;

  // Get blog data from Parse Blog Content node
  let blogData = {};
  try {
    const parseContentData = $('Parse Blog Content').all();
    if (parseContentData && parseContentData.length > 0) {
      blogData = parseContentData[0].json;
    }
  } catch (e) {
    console.log("Could not access Parse Blog Content data:", e.message);
    blogData = inputs[1]?.json || {};
  }

  // Initialize SEO data with defaults
  let seoData = {
    primary_keyword: "health",
    secondary_keywords: [],
    meta_description: "Learn about natural health solutions and wellness tips.",
    readability_score: 70,
    recommendations: "No specific recommendations available"
  };

  // Try to extract content from OpenAI-style response
  if (seoResponse && seoResponse.choices && seoResponse.choices[0]) {
    try {
      const content = seoResponse.choices[0].message?.content?.trim() || "";

      // Remove markdown code blocks if present
      const cleanContent = content.replace(/```json\s*/, '').replace(/```\s*$/, '');

      // Try to parse as JSON
      const parsedSeo = JSON.parse(cleanContent);

      seoData = {
        ...seoData,
        ...parsedSeo
      };
    } catch (e) {
      console.error("Failed to parse OpenAI SEO JSON:", e);
      seoData.recommendations = "Parsing failed. Please check the raw SEO response.";
    }
  } 
  // Fallback: Try to parse from plain JSON string (e.g. "text" field)
  else if (seoResponse && seoResponse.text) {
    try {
      const content = seoResponse.text.trim();
      const cleanContent = content.replace(/```json\s*/, '').replace(/```\s*$/, '');

      const parsedSeo = JSON.parse(cleanContent);
      seoData = {
        ...seoData,
        ...parsedSeo
      };
    } catch (e) {
      console.error("Failed to parse SEO JSON from text field:", e);
      seoData.recommendations = "Parsing failed. Please check the raw SEO response.";
    }
  } 
  // If neither format is valid, use defaults
  else {
    console.warn("No valid SEO response format detected");
  }

  // Merge with blog data
  const finalData = {
    ...blogData,
    seo_data: seoData,
    final_timestamp: new Date().toISOString()
  };

  return [{ json: finalData }];
} catch (error) {
  console.error("Error in Parse SEO Data node:", error);
  return [{ json: {
    error: "SEO Analysis Failed",
    details: error.message,
    title: "SEO Processing Error",
    content: "<p>SEO analysis could not be completed</p>",
    timestamp: new Date().toISOString()
  } }];
}

