  let themes = [];

  // Extract themes from title
  const titleWords = title.toLowerCase();
  if (titleWords.includes('smart') || titleWords.includes('ai')) themes.push('smart parking technology');
  if (titleWords.includes('parking') || titleWords.includes('management')) themes.push('parking management');
  if (titleWords.includes('urban') || titleWords.includes('city')) themes.push('urban mobility');
  if (titleWords.includes('algorithm') || titleWords.includes('optimization')) themes.push('parking optimization');
  if (titleWords.includes('revenue') || titleWords.includes('cost')) themes.push('parking economics');
  if (titleWords.includes('technology') || titleWords.includes('system')) themes.push('parking technology');
