}

try {
  const inputs = $input.all();
  const imageResponse = inputs[0];

  console.log('=== IMAGE GENERATION COMPLETE (BINARY MODE) ===');
  console.log('Response type:', typeof imageResponse);
  console.log('Has binary data:', !!(imageResponse && imageResponse.binary));

  // Handle binary image data from DALL-E 3
  let imageData = null;
  let imageGenerated = false;
  let base64Image = null;

  if (imageResponse && imageResponse.binary) {
    // Convert binary to base64 for email embedding
    try {
      const binaryData = imageResponse.binary.data;
      const mimeType = imageResponse.binary.mimeType || 'image/png';

      if (binaryData) {
        // Create data URL for embedding in email
        base64Image = `data:${mimeType};base64,${binaryData.toString('base64')}`;
        imageData = {
          binary: binaryData,
          mimeType: mimeType,
          base64: base64Image,
          size: binaryData.length
        };
        imageGenerated = true;
        console.log('✅ Binary image processed successfully');
        console.log('- MIME type:', mimeType);
        console.log('- Size:', binaryData.length, 'bytes');
      }
    } catch (conversionError) {
      console.log('❌ Binary conversion failed:', conversionError.message);
    }
  } else if (imageResponse && imageResponse.json && imageResponse.json.data && imageResponse.json.data[0]) {
    // Fallback: Handle URL format if still present
    const imageUrl = imageResponse.json.data[0].url;
    if (imageUrl) {
      imageData = { url: imageUrl };
      base64Image = imageUrl; // For backward compatibility
      imageGenerated = true;
      console.log('✅ Fallback: Image URL extracted:', imageUrl);
    }
  } else {
    console.log('❌ No image data found in response');
    console.log('Available fields:', Object.keys(imageResponse || {}));
  }

  // Get the original prompt data
  const promptData = $('Generate Image Prompt').all()[0]?.json || {};

  const finalData = {
    title: promptData.title || "Blog Image",
    image_data: imageData,
    image_base64: base64Image,
    image_generated: imageGenerated,
    detected_themes: promptData.detected_themes || [],
    image_prompt: promptData.image_prompt || "",
    generation_timestamp: new Date().toISOString(),
    status: imageGenerated ? "success" : "failed",
    format: "binary"
  };

  console.log('Final image data:', {
    title: finalData.title,
    image_generated: finalData.image_generated,
    status: finalData.status,
    has_base64: !!finalData.image_base64,
    format: finalData.format
  });

  return [{ json: finalData }];

} catch (error) {
  console.log('❌ Error in image processing:', error.message);

  return [{ json: {
    title: "Blog Image",
    image_data: null,
    image_base64: null,
    image_generated: false,
    error: error.message,
    status: "error",
    format: "binary",
    generation_timestamp: new Date().toISOString()
  } }];
}
